const BATA_CATEGORY_LABELS = {
  'comportamiento':    'Comportamiento',
  'neuropsicologia':   'Neuropsicología',
  'psicologia-social': 'Psicología Social',
  'rendimiento':       'Rendimiento',
  'salud':             'Salud',
  'clinica':           'Clínica',
  'educacion':         'Educación',
  'organizacional':    'Organizacional',
};

let _bataApplyFilter = null;

function initBataFilter() {
  const grid = document.getElementById('docs-grid-2');
  if (!grid) return;

  const cards      = [...grid.querySelectorAll('.doc-card')];
  const categories = [...new Set(cards.map(c => c.dataset.category).filter(Boolean))];

  const pillsWrap = document.createElement('div');
  pillsWrap.className = 'bata-filter-pills';
  pillsWrap.id = 'bata-filter-pills';
  pillsWrap.innerHTML =
    `<button class="bata-pill active" data-filter="todos">Todos</button>` +
    categories.map(cat =>
      `<button class="bata-pill" data-filter="${cat}">${BATA_CATEGORY_LABELS[cat] || cat}</button>`
    ).join('');

  grid.insertAdjacentElement('beforebegin', pillsWrap);

  function applyFilter(filter) {
    pillsWrap.querySelectorAll('.bata-pill').forEach(p => p.classList.toggle('active', p.dataset.filter === filter));
    cards.forEach(card => {
      card.style.display = (filter === 'todos' || card.dataset.category === filter) ? '' : 'none';
    });
  }
  _bataApplyFilter = applyFilter;

  pillsWrap.addEventListener('click', e => {
    const pill = e.target.closest('.bata-pill');
    if (!pill) return;
    applyFilter(pill.dataset.filter);
  });
}

/* Tarjetas de sección: abren el listado filtrado en overlay */
function initBataSecciones() {
  const grid      = document.getElementById('docs-grid-2');
  const tilesWrap = document.getElementById('bata-secciones');
  if (!grid || !tilesWrap) return;

  const cards  = [...grid.querySelectorAll('.doc-card')];
  const counts = {};
  cards.forEach(c => {
    const cat = c.dataset.category;
    if (cat) counts[cat] = (counts[cat] || 0) + 1;
  });

  const arrow = `<svg class="bata-seccion-tile-arrow" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="9 18 15 12 9 6"/></svg>`;

  tilesWrap.innerHTML = Object.entries(counts).map(([cat, n]) => `
    <button class="bata-seccion-tile" data-cat="${cat}" aria-haspopup="dialog">
      <span class="bata-seccion-tile-body">
        <span class="bata-seccion-tile-titulo">${BATA_CATEGORY_LABELS[cat] || cat}</span>
        <span class="bata-seccion-tile-count">${n} artículo${n === 1 ? '' : 's'}</span>
      </span>
      ${arrow}
    </button>`).join('') + `
    <button class="bata-seccion-tile bata-ver-todos" data-cat="todos" aria-haspopup="dialog">
      <span class="bata-seccion-tile-body">
        <span class="bata-seccion-tile-titulo">Ver todos</span>
        <span class="bata-seccion-tile-count">${cards.length} artículos</span>
      </span>
      ${arrow}
    </button>`;

  tilesWrap.addEventListener('click', e => {
    const tile = e.target.closest('.bata-seccion-tile');
    if (!tile) return;
    openBataModal(tile.dataset.cat);
  });
}

/* Fade-in escalonado de las tarjetas al hacer scroll dentro del modal */
let _bataCardObserver = null;

function initBataCardFadeIn() {
  const modalCard = document.querySelector('#bata-lista-modal .concepto-modal-card');
  const grid      = document.getElementById('docs-grid-2');
  if (!modalCard || !grid) return;
  if (_bataCardObserver) _bataCardObserver.disconnect();
  const cards = grid.querySelectorAll('.doc-card');
  cards.forEach(c => c.classList.remove('card-in-view'));
  _bataCardObserver = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (!entry.isIntersecting) return;
      entry.target.classList.add('card-in-view');
      _bataCardObserver.unobserve(entry.target);
    });
  }, { root: modalCard, threshold: 0.12, rootMargin: '0px 0px -40px 0px' });
  cards.forEach(c => _bataCardObserver.observe(c));
}

/* Modal de listado: overlay con blur, igual que Explorar concepto */
let _bataModalTrap = null, _bataModalTrigger = null;

function openBataModal(cat, focusEl) {
  const modal = document.getElementById('bata-lista-modal');
  const title = document.getElementById('blm-titulo');
  if (!modal) return;
  if (_bataApplyFilter) _bataApplyFilter(cat || 'todos');
  if (title) title.textContent = (cat && cat !== 'todos') ? (BATA_CATEGORY_LABELS[cat] || cat) : 'Todos los artículos';
  _bataModalTrigger = document.activeElement;
  modal.hidden = false;
  document.body.style.overflow = 'hidden';
  _bataModalTrap = trapFocus(modal);
  initBataCardFadeIn();
  requestAnimationFrame(() => {
    if (focusEl) focusEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
    else document.getElementById('bata-lista-modal-close')?.focus();
  });
}

function closeBataModal() {
  const modal = document.getElementById('bata-lista-modal');
  if (!modal || modal.hidden) return;
  modal.hidden = true;
  document.body.style.overflow = '';
  if (_bataModalTrap) { releaseFocus(modal, _bataModalTrap, _bataModalTrigger); _bataModalTrap = null; }
  else if (_bataModalTrigger) _bataModalTrigger.focus();
}
window._LI_openBataModal = openBataModal;

(function () {
  const modal = document.getElementById('bata-lista-modal');
  const closeBtn = document.getElementById('bata-lista-modal-close');
  if (!modal) return;
  /* Sacarlo de #mob-slide-wrap: su `contain` en móvil rompe el position:fixed del modal */
  document.body.appendChild(modal);
  if (closeBtn) {
    closeBtn.addEventListener('click', closeBataModal);
    closeBtn.addEventListener('touchstart', e => { e.preventDefault(); closeBataModal(); }, { passive: false });
  }
  modal.addEventListener('click', e => { if (e.target === modal) closeBataModal(); });
  modal.addEventListener('touchstart', e => { if (e.target === modal) { e.preventDefault(); closeBataModal(); } }, { passive: false });
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape' && !modal.hidden) closeBataModal();
  });
}());

function initBataArticles() {
  const bataView  = document.getElementById('bata-article-view');
  const bataCards = document.getElementById('documentos-list');
  if (!bataView || !bataCards) return;
  document.querySelectorAll('[data-bata-id] .btn-leer-bata').forEach(btn => {
    btn.addEventListener('click', e => {
      e.stopPropagation();
      const id  = btn.closest('[data-bata-id]').dataset.bataId;
      const art = BATA_ARTICLES.find(a => a.id === id);
      if (!art) return;
      closeBataModal();
      bataView.innerHTML = renderBataFull(art);
      bataCards.style.display = 'none';
      bataView.style.display  = '';
      bataView.scrollIntoView({ behavior: 'smooth', block: 'start' });
      document.getElementById('bata-back-btn')?.addEventListener('click', () => {
        bataView.style.display  = 'none';
        bataCards.style.display = '';
        bataView.innerHTML      = '';
        bataCards.scrollIntoView({ behavior: 'smooth', block: 'start' });
      });
    });
  });
}

document.addEventListener('DOMContentLoaded', () => {
  initBataFilter();
  initBataSecciones();
  initBataArticles();

  /* Contador dinámico de artículos en stats bar */
  const statsEl = document.getElementById('stats-article-count');
  if (statsEl) statsEl.textContent = Object.values(LIBRARY_ARTICLES).flat().length;

  /* Footer glosario link */
  document.getElementById('footer-glosario-link')?.addEventListener('click', e => {
    e.preventDefault();
    if (window._LI_openGlosario) window._LI_openGlosario();
  });

  /* Footer tab links */
  document.querySelectorAll('[data-tab-footer]').forEach(link => {
    link.addEventListener('click', e => {
      e.preventDefault();
      const target = link.dataset.tabFooter;
      const btn = document.querySelector(`[data-tab="${target}"]`);
      if (btn) btn.click();
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  });
});

function _buildTocHTML(sections) {
  if (!sections || sections.length < 2) return '';
  const links = sections.map((s, i) => s.tocSkip ? null : `<li><a class="toc-link" href="#art-sec-${i}">${s.subtitle}</a></li>`).filter(Boolean);
  if (links.length < 2) return '';
  return `<nav class="article-toc" aria-label="Índice del artículo">
    <span class="toc-label">
      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><line x1="8" y1="6" x2="21" y2="6"/><line x1="8" y1="12" x2="21" y2="12"/><line x1="8" y1="18" x2="21" y2="18"/><line x1="3" y1="6" x2="3.01" y2="6"/><line x1="3" y1="12" x2="3.01" y2="12"/><line x1="3" y1="18" x2="3.01" y2="18"/></svg>
      Índice
    </span>
    <ol class="toc-list">${links.join('')}</ol>
  </nav>`;
}

function _buildStatsHTML(id) {
  const stats = ARTICLE_STATS[id];
  if (!stats || !stats.length) return '';
  return `<div class="stat-callout-row">${stats.map(s =>
    `<div class="stat-callout">
      <span class="stat-value">${s.value}</span>
      <span class="stat-label">${s.label}</span>
      <span class="stat-detail">${s.detail}</span>
    </div>`
  ).join('')}</div>`;
}

function _buildRecomendacionHTML(id) {
  const rec = (window.RECOMENDACIONES || {})[id];
  if (!rec || !rec.libro) return '';
  const { libro } = rec;
  return `<div class="recomendacion-block">
    <p class="recomendacion-label">Si quieres profundizar en esto</p>
    <div class="recomendacion-libro">
      <div class="recomendacion-libro-info">
        <strong>${libro.titulo}</strong>
        <span class="recomendacion-autor">${libro.autor}</span>
        <p>${libro.sinopsis}</p>
      </div>
      <a href="${libro.amazon}" class="recomendacion-btn" target="_blank" rel="noopener noreferrer sponsored" data-umami-event="audible-click" data-umami-event-libro="${libro.titulo}" data-umami-event-origen="articulo-spa">Consigue este audiolibro gratis</a>
    </div>
    <p class="recomendacion-valor">Además, tienes acceso a miles de audiolibros más durante 30 días, sin coste.</p>
    <p class="recomendacion-disclaimer">Enlace de afiliado.</p>
  </div>`;
}

