/* ── ONBOARDING TOUR, primera visita ───────────────────────── */
(function () {
  const LS_KEY = 'li_onboarded';
  if (lsGet(LS_KEY)) return;

  const isMob  = () => window.innerWidth <= 768;
  const CHEVRON = `<svg class="ob-chevron" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="9 18 15 12 9 6"/></svg>`;

  const TOUR_STEPS = [
    {
      type: 'intereses',
      eyebrow: 'Bienvenido/a a La Inferencia',
      title: '¿Qué temas te interesan?',
      text: 'Elige 3 y empezamos por ahí. Psicología real, contada como se explica a un amigo, no como en un manual.',
      icon: `<img src="img/logo2.png" alt="La Inferencia" />`,
    },
    {
      type: 'modal',
      noSkip: true,
      hideIcon: true,
      title: 'Tienes un regalo esperando',
      rewardHook: 'Sabemos que te gusta aprender, aunque el tiempo no siempre da para leer todo lo que querrías.',
      rewardHighlight: 'Lee tus primeros 4 artículos y desbloquea un regalo',
      rewardBadge: '🎁 Normalmente hay que pagarlo. Te lo hemos conseguido gratis.',
    },
  ];

  /* ── DOM refs ─────────────────────────────────────────────── */
  const ring         = document.getElementById('tour-ring');
  const dim          = document.getElementById('tour-dim');
  const shell        = document.getElementById('tour-shell');
  const tooltip      = document.getElementById('tour-tooltip');
  const modal        = document.getElementById('tour-modal');
  const nextBtn      = document.getElementById('tour-next');
  const skipBtn      = document.getElementById('tour-skip');
  const mNext        = document.getElementById('tour-modal-next');
  const mSkip        = document.getElementById('tour-modal-skip');
  const dotsWrap     = document.getElementById('tour-dots');
  const tooltipDots  = document.getElementById('tour-dots-tt');
  const progressFill = document.getElementById('tour-progress-fill');
  const arrow        = document.getElementById('tour-arrow');
  if (!dim || !shell || !tooltip || !modal) return;

  /* ── State ────────────────────────────────────────────────── */
  let current       = 0;
  let transitioning = false;
  let prevTarget    = null;
  let prevParent    = null;
  let prevParentZ   = '';
  let trapHandler   = null;
  let resizeTimer   = null;
  const TOTAL       = TOUR_STEPS.length;

  /* ── Build progress dots (modal + tooltip) ────────────────── */
  [dotsWrap, tooltipDots].forEach(wrap => {
    if (!wrap) return;
    TOUR_STEPS.forEach((_, i) => {
      const dot = document.createElement('span');
      dot.className = 'onboarding-dot' + (i === 0 ? ' active' : '');
      wrap.appendChild(dot);
    });
  });

  /* ── Helpers ──────────────────────────────────────────────── */
  function updateDots() {
    [dotsWrap, tooltipDots].forEach(wrap => {
      if (!wrap) return;
      Array.from(wrap.querySelectorAll('.onboarding-dot'))
        .forEach((d, i) => d.classList.toggle('active', i === current));
    });
  }

  function updateBtns() {
    const isLast = current === TOTAL - 1;
    const label  = (isLast ? '¡Empezar! ' : 'Siguiente ') + CHEVRON;
    nextBtn.innerHTML = label;
    mNext.innerHTML   = label;
    const sc = document.getElementById('tour-step-counter');
    if (sc) sc.textContent = (current + 1) + ' de ' + TOTAL;
  }

  function updateProgress() {
    if (progressFill) progressFill.style.width = ((current + 1) / TOTAL * 100) + '%';
  }

  function isElementVisible(el) {
    const r = el.getBoundingClientRect();
    if (r.width < 10 || r.height < 10) return false;
    const cs = window.getComputedStyle(el);
    if (cs.display === 'none' || cs.visibility === 'hidden') return false;
    let a = el.parentElement;
    while (a && a !== document.body) {
      if (window.getComputedStyle(a).display === 'none' || a.hidden) return false;
      a = a.parentElement;
    }
    return true;
  }

  function clearSpotlight() {
    if (prevTarget) { prevTarget.classList.remove('tour-spotlight-target'); prevTarget = null; }
    if (prevParent) { prevParent.style.zIndex = prevParentZ; prevParent = null; prevParentZ = ''; }
    setDockRaised(false);
  }

  function setDockRaised(on) {
    const dock = document.getElementById('mobile-bottom-nav');
    if (dock) dock.classList.toggle('tour-dock-raised', on);
  }

  function positionRing(target) {
    if (!ring) return;
    const PAD = 8;
    const r   = target.getBoundingClientRect();
    const cs  = window.getComputedStyle(target);
    const br  = parseFloat(cs.borderTopLeftRadius) || 8;
    ring.style.top          = (r.top    - PAD) + 'px';
    ring.style.left         = (r.left   - PAD) + 'px';
    ring.style.width        = (r.width  + PAD * 2) + 'px';
    ring.style.height       = (r.height + PAD * 2) + 'px';
    ring.style.borderRadius = Math.min(br + PAD, 20) + 'px';
    ring.hidden             = false;
    ring.style.opacity      = '1';
  }

  function hideRing() {
    if (!ring) return;
    ring.style.opacity = '0';
  }

  /* ── Tooltip positioning (desktop) ───────────────────────── */
  function positionTooltip(target, preferred) {
    const TW   = 320;
    const GAP  = 16;
    const ARW  = 10;
    const MARG = 12;
    const TH   = tooltip.offsetHeight || 240;

    const tr  = target.getBoundingClientRect();
    const vw  = window.innerWidth;
    const vh  = window.innerHeight;

    const space = {
      above: tr.top    - GAP - ARW,
      below: vh - tr.bottom - GAP - ARW,
      left:  tr.left   - GAP - ARW,
      right: vw - tr.right  - GAP - ARW,
    };
    const fits = {
      above: space.above >= TH,
      below: space.below >= TH,
      left:  space.left  >= TW,
      right: space.right >= TW,
    };
    const FALLBACKS = {
      above: ['above', 'below', 'right', 'left'],
      below: ['below', 'above', 'right', 'left'],
      left:  ['left', 'right', 'above', 'below'],
      right: ['right', 'left', 'below', 'above'],
    };
    const order = FALLBACKS[preferred] || FALLBACKS['below'];
    const side  = order.find(s => fits[s]) || preferred;

    const midY = Math.min(
      Math.max(tr.top + tr.height / 2, tr.top + 40),
      Math.min(tr.bottom - 40, vh * 0.55)
    );

    let top, left;
    if (side === 'above') {
      top  = tr.top - TH - GAP - ARW;
      left = tr.left + tr.width / 2 - TW / 2;
    } else if (side === 'below') {
      top  = tr.bottom + GAP + ARW;
      left = tr.left + tr.width / 2 - TW / 2;
    } else if (side === 'left') {
      top  = midY - TH / 2;
      left = tr.left - TW - GAP - ARW;
    } else {
      top  = midY - TH / 2;
      left = tr.right + GAP + ARW;
    }

    left = Math.max(MARG, Math.min(left, vw - TW - MARG));
    top  = Math.max(MARG, Math.min(top,  vh - TH - MARG));

    tooltip.style.cssText = 'position:fixed;top:' + top + 'px;left:' + left + 'px;width:' + TW + 'px;';

    arrow.className = 'tour-arrow tour-arrow--' + side;
    arrow.style.left = '';
    arrow.style.top  = '';
    if (side === 'above' || side === 'below') {
      const offset = Math.max(16, Math.min(tr.left + tr.width / 2 - left, TW - 16));
      arrow.style.left = offset + 'px';
    } else {
      const offset = Math.max(16, Math.min(midY - top, TH - 16));
      arrow.style.top = offset + 'px';
    }
  }

  /* ── Render: modal centrado ───────────────────────────────── */
  function renderModal(step) {
    clearSpotlight();
    hideRing();
    dim.hidden     = true;
    tooltip.hidden = true;
    modal.hidden   = false;
    shell.hidden   = false;

    const iconEl = document.getElementById('tour-modal-icon');
    iconEl.innerHTML = step.icon || '';
    iconEl.hidden    = !!step.hideIcon;
    document.getElementById('tour-modal-title').textContent = step.title;

    const textEl   = document.getElementById('tour-modal-text');
    const rewardEl = document.getElementById('tour-modal-reward');
    if (step.rewardHighlight) {
      textEl.hidden   = true;
      rewardEl.hidden = false;
      document.getElementById('tour-modal-reward-hook').textContent      = step.rewardHook || '';
      document.getElementById('tour-modal-reward-highlight').textContent = step.rewardHighlight;
      document.getElementById('tour-modal-reward-badge').textContent     = step.rewardBadge || '';
    } else {
      textEl.hidden   = false;
      rewardEl.hidden = true;
      textEl.textContent = step.text;
    }

    const eyebrowEl = document.getElementById('tour-modal-eyebrow');
    if (eyebrowEl) {
      eyebrowEl.textContent = step.eyebrow || '';
      eyebrowEl.hidden      = !step.eyebrow;
    }

    const chipsWrap = document.getElementById('tour-modal-chips');
    const counterEl = document.getElementById('tour-modal-counter');
    if (chipsWrap)  chipsWrap.hidden  = true;
    if (counterEl)  counterEl.hidden  = true;
    mSkip.hidden    = !!step.noSkip;
    mNext.disabled  = false;
    mNext.classList.remove('ob-ready');

    iconEl.classList.remove('icon-retrigger');
    void iconEl.offsetWidth;
    iconEl.classList.add('icon-retrigger');

    if (trapHandler) { releaseFocus(shell, trapHandler); trapHandler = null; }
    trapHandler = trapFocus(shell);
    mNext.focus();
  }

  /* ── Render: selector de intereses obligatorio (paso 0) ────── */
  function renderInterestPicker(step) {
    clearSpotlight();
    hideRing();
    dim.hidden     = true;
    tooltip.hidden = true;
    modal.hidden   = false;
    shell.hidden   = false;

    document.getElementById('tour-modal-icon').innerHTML    = step.icon;
    document.getElementById('tour-modal-title').textContent = step.title;
    document.getElementById('tour-modal-text').textContent  = step.text;

    const eyebrowEl = document.getElementById('tour-modal-eyebrow');
    if (eyebrowEl) {
      eyebrowEl.textContent = step.eyebrow || '';
      eyebrowEl.hidden      = !step.eyebrow;
    }

    const chipsWrap   = document.getElementById('tour-modal-chips');
    const counterEl   = document.getElementById('tour-modal-counter');
    const textEl      = document.getElementById('tour-modal-text');
    const baseText    = step.text;
    const labels = window.LI_CAT_LABELS || {};
    const icons  = window.LI_CAT_ICONS  || {};
    const noMotion = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
    chipsWrap.innerHTML =
      '<svg class="ob-constellation" aria-hidden="true"></svg>' +
      Object.keys(labels).map((id, i) =>
        `<button type="button" class="onboarding-chip" data-cat="${id}" style="--ci:${i}">${icons[id] || ''}<span>${labels[id]}</span></button>`
      ).join('');
    chipsWrap.hidden   = false;
    counterEl.hidden   = false;
    mSkip.hidden       = true;
    mNext.disabled     = true;

    const svg      = chipsWrap.querySelector('.ob-constellation');
    const selected = new Set();

    function updateCounter() {
      const n = selected.size;
      counterEl.innerHTML =
        '<span class="ob-count-dots" aria-hidden="true">' +
        [0, 1, 2].map(i => `<i class="${i < n ? 'on' : ''}"></i>`).join('') +
        '</span><span>' + n + ' / 3 elegidos</span>';
    }

    function updateSubtitle() {
      let txt = baseText;
      if (selected.size === 3) {
        const names = Array.from(selected).map(id => labels[id]);
        const list  = names.slice(0, -1).join(', ') + ' y ' + names[names.length - 1];
        txt = list + '. Buena mezcla, empezamos por ahí.';
      }
      if (txt === textEl.textContent) return;
      textEl.classList.remove('ob-swap');
      void textEl.offsetWidth;
      textEl.textContent = txt;
      if (!noMotion) textEl.classList.add('ob-swap');
    }

    function drawConstellation(newCat) {
      const pts = Array.from(chipsWrap.querySelectorAll('.onboarding-chip.selected')).map(c => ({
        cat: c.dataset.cat,
        x: c.offsetLeft + c.offsetWidth / 2,
        y: c.offsetTop  + c.offsetHeight / 2
      }));
      const segs = [];
      for (let i = 0; i < pts.length; i++)
        for (let j = i + 1; j < pts.length; j++)
          segs.push([pts[i], pts[j]]);

      const linesSvg = segs.map(([a, b]) =>
        `<line x1="${a.x.toFixed(1)}" y1="${a.y.toFixed(1)}" x2="${b.x.toFixed(1)}" y2="${b.y.toFixed(1)}"></line>`
      ).join('');

      const pulsesSvg = noMotion ? '' : segs.map(([a, b]) => {
        const begin = (0.65 + Math.random() * 1.4).toFixed(2);
        return `<circle class="ob-pulse" r="2.4">` +
          `<animate attributeName="opacity" values="0;1;1;0" dur="1.9s" begin="${begin}s" repeatCount="indefinite"/>` +
          `<animateMotion dur="1.9s" begin="${begin}s" repeatCount="indefinite" ` +
          `path="M ${a.x.toFixed(1)} ${a.y.toFixed(1)} L ${b.x.toFixed(1)} ${b.y.toFixed(1)}"/>` +
          `</circle>`;
      }).join('');

      const nodesSvg = pts.map(p => {
        const isNew = !noMotion && p.cat === newCat;
        return `<circle class="ob-node-halo" cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="9"></circle>` +
          (isNew ? `<circle class="ob-node-land-wave" cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="4"></circle>` : '') +
          `<circle class="ob-node${isNew ? ' ob-node--new' : ''}" cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="3.5"></circle>`;
      }).join('');

      svg.innerHTML = linesSvg + pulsesSvg + nodesSvg;

      if (!noMotion && segs.length) {
        const lns = svg.querySelectorAll('line');
        segs.forEach(([a, b], k) => {
          const len = Math.hypot(b.x - a.x, b.y - a.y).toFixed(1);
          lns[k].style.strokeDasharray  = len;
          lns[k].style.strokeDashoffset = len;
        });
        void svg.getBoundingClientRect();
        lns.forEach(ln => { ln.style.strokeDashoffset = '0'; });
      }

      if (!noMotion && pts.length === 3) {
        svg.classList.remove('ob-complete');
        void svg.getBoundingClientRect();
        svg.classList.add('ob-complete');
        clearTimeout(drawConstellation._t);
        drawConstellation._t = setTimeout(() => svg.classList.remove('ob-complete'), 900);
      } else {
        svg.classList.remove('ob-complete');
      }
    }

    updateCounter();

    chipsWrap.querySelectorAll('.onboarding-chip').forEach(chip => {
      chip.addEventListener('click', () => {
        const cat = chip.dataset.cat;
        if (selected.has(cat)) {
          selected.delete(cat);
          chip.classList.remove('selected');
        } else if (selected.size < 3) {
          selected.add(cat);
          chip.classList.add('selected');
        }
        const full = selected.size === 3;
        chipsWrap.querySelectorAll('.onboarding-chip').forEach(c => {
          c.disabled = full && !c.classList.contains('selected');
        });
        mNext.disabled = !full;
        mNext.classList.toggle('ob-ready', full);
        updateCounter();
        updateSubtitle();
        drawConstellation(selected.has(cat) ? cat : null);
        if (full) lsSet('li_intereses', JSON.stringify(Array.from(selected)));
      });
    });

    window.addEventListener('resize', drawConstellation, { passive: true });

    const iconEl = document.getElementById('tour-modal-icon');
    iconEl.classList.remove('icon-retrigger');
    void iconEl.offsetWidth;
    iconEl.classList.add('icon-retrigger');

    if (trapHandler) { releaseFocus(shell, trapHandler); trapHandler = null; }
    trapHandler = trapFocus(shell);
  }

  /* ── Render: spotlight sobre elemento ──────────────────────── */
  function renderSpotlight(step) {
    const mob = isMob();
    const activeSel = mob
      ? (step.mobileActivateSelector || step.activateSelector)
      : step.activateSelector;
    let navDelay = 0;
    if (activeSel) {
      const activateEl = document.querySelector(activeSel);
      if (activateEl) { activateEl.click(); navDelay = 380; }
    }
    setTimeout(() => _doSpotlight(step, mob), navDelay);
  }

  function _doSpotlight(step, mob) {
    const targetSel = (mob && step.mobileTargetSelector) ? step.mobileTargetSelector : step.targetSelector;
    const target    = targetSel ? document.querySelector(targetSel) : null;
    if (!target) {
      if (mob) renderBottomSheet(step);
      else renderCenteredTooltip(step);
      return;
    }
    if (!isElementVisible(target) && mob) {
      renderBottomSheet(step);
      return;
    }

    target.scrollIntoView({ behavior: 'smooth', block: 'center' });

    const doPosition = () => {
      clearSpotlight();
      prevTarget = target;
      target.classList.add('tour-spotlight-target');
      setDockRaised(mob && !!target.closest('#mobile-bottom-nav'));

      if (step.raiseParent && !mob) {
        prevParent = document.querySelector(step.raiseParent);
        if (prevParent) { prevParentZ = prevParent.style.zIndex; prevParent.style.zIndex = '1002'; }
      }

      dim.hidden   = false;
      modal.hidden = true;

      document.getElementById('tour-tooltip-icon').innerHTML = step.icon;
      document.getElementById('tour-title').textContent       = step.title;
      document.getElementById('tour-text').textContent        = step.text;

      positionRing(target);
      updateProgress();

      tooltip.hidden = false;
      shell.hidden   = false;

      if (mob) {
        tooltip.style.cssText = '';
        tooltip.classList.remove('tour-tooltip--centered');
        tooltip.classList.add('tour-tooltip--bottom-sheet');
        arrow.hidden = true;
      } else {
        tooltip.classList.remove('tour-tooltip--centered', 'tour-tooltip--bottom-sheet');
        arrow.hidden = false;
        positionTooltip(target, step.tooltipPosition);
      }

      if (trapHandler) { releaseFocus(shell, trapHandler); trapHandler = null; }
      trapHandler = trapFocus(shell);
      nextBtn.focus();
    };

    if ('onscrollend' in window) {
      const onEnd = () => { window.removeEventListener('scrollend', onEnd); doPosition(); };
      window.addEventListener('scrollend', onEnd, { once: true });
      setTimeout(() => { window.removeEventListener('scrollend', onEnd); doPosition(); }, 400);
    } else {
      setTimeout(doPosition, 220);
    }
  }

  /* ── Render: tooltip centrado (fallback desktop) ──────────── */
  function renderCenteredTooltip(step) {
    clearSpotlight();
    hideRing();
    dim.hidden   = false;
    modal.hidden = true;

    document.getElementById('tour-tooltip-icon').innerHTML = step.icon;
    document.getElementById('tour-title').textContent       = step.title;
    document.getElementById('tour-text').textContent        = step.text;

    tooltip.style.cssText = '';
    tooltip.classList.remove('tour-tooltip--bottom-sheet');
    tooltip.classList.add('tour-tooltip--centered');
    arrow.hidden = true;

    tooltip.hidden = false;
    shell.hidden   = false;

    updateProgress();

    if (trapHandler) { releaseFocus(shell, trapHandler); trapHandler = null; }
    trapHandler = trapFocus(shell);
    nextBtn.focus();
  }

  /* ── Render: bottom sheet (móvil, siempre) ───────────────── */
  function renderBottomSheet(step) {
    clearSpotlight();
    hideRing();
    dim.hidden   = false;
    modal.hidden = true;

    document.getElementById('tour-tooltip-icon').innerHTML = step.icon;
    document.getElementById('tour-title').textContent       = step.title;
    document.getElementById('tour-text').textContent        = step.text;

    tooltip.style.cssText = '';
    tooltip.classList.remove('tour-tooltip--centered');
    tooltip.classList.add('tour-tooltip--bottom-sheet');
    arrow.hidden = true;

    tooltip.hidden = false;
    shell.hidden   = false;

    updateProgress();

    if (trapHandler) { releaseFocus(shell, trapHandler); trapHandler = null; }
    trapHandler = trapFocus(shell);
    nextBtn.focus();
  }

  /* ── Navegación ───────────────────────────────────────────── */
  function renderStep(n) {
    updateDots();
    updateBtns();
    const step = TOUR_STEPS[n];
    if (step.type === 'intereses') renderInterestPicker(step);
    else if (step.type === 'modal') renderModal(step);
    else renderSpotlight(step);
  }

  function goTo(n, dir = 1) {
    if (transitioning || n < 0 || n >= TOTAL) return;
    transitioning = true;

    const nextStep = TOUR_STEPS[n];
    const currStep = TOUR_STEPS[current];
    const mob = isMob();

    // Transición fluida desktop: spotlight → spotlight con card posicionada
    if (!tooltip.hidden && !mob
        && currStep.type === 'spotlight' && nextStep.type === 'spotlight'
        && !tooltip.classList.contains('tour-tooltip--centered')
        && !tooltip.classList.contains('tour-tooltip--bottom-sheet')) {

      const FADE   = 140;
      const SLIDE  = 380;
      const CONTENT = ['tour-tooltip-icon', 'tour-title', 'tour-text'];

      const targetSel = nextStep.targetSelector;
      const target    = targetSel ? document.querySelector(targetSel) : null;

      if (target && isElementVisible(target)) {
        current = n;
        updateDots();
        updateBtns();
        updateProgress();

        // 1. Fade out simultáneo con el inicio del movimiento
        CONTENT.forEach(id => {
          const el = document.getElementById(id);
          if (el) { el.style.transition = `opacity ${FADE}ms ease`; el.style.opacity = '0'; }
        });

        // 2. Activar tab
        const activateEl = nextStep.activateSelector ? document.querySelector(nextStep.activateSelector) : null;
        if (activateEl) activateEl.click();

        // 2b. Si el target no está en el viewport, llevar al usuario hasta él
        const tRect  = target.getBoundingClientRect();
        const inView = tRect.top >= 0 && tRect.bottom <= window.innerHeight;
        if (!inView) target.scrollIntoView({ behavior: 'smooth', block: 'center' });

        // 3. Mover ring+card (tras el scroll, si hizo falta)
        const positionAndSwap = () => {
          if (prevTarget) { prevTarget.classList.remove('tour-spotlight-target'); prevTarget = null; }
          if (prevParent) { prevParent.style.zIndex = prevParentZ; prevParent = null; prevParentZ = ''; }
          prevTarget = target;
          target.classList.add('tour-spotlight-target');
          if (nextStep.raiseParent) {
            prevParent = document.querySelector(nextStep.raiseParent);
            if (prevParent) { prevParentZ = prevParent.style.zIndex; prevParent.style.zIndex = '1002'; }
          }
          positionRing(target);

          // Card se desliza a nueva posición (transición CSS)
          tooltip.classList.add('tour-tooltip--sliding');
          positionTooltip(target, nextStep.tooltipPosition || 'below');

          // Tras fade out, actualizar contenido y hacer fade in
          setTimeout(() => {
            document.getElementById('tour-tooltip-icon').innerHTML = nextStep.icon;
            document.getElementById('tour-title').textContent       = nextStep.title;
            document.getElementById('tour-text').textContent        = nextStep.text;

            requestAnimationFrame(() => requestAnimationFrame(() => {
              CONTENT.forEach(id => {
                const el = document.getElementById(id);
                if (el) el.style.opacity = '1';
              });
              // Limpiar al finalizar slide, sin parpadeo
              setTimeout(() => {
                CONTENT.forEach(id => {
                  const el = document.getElementById(id);
                  if (el) { el.style.transition = ''; el.style.opacity = ''; }
                });
                tooltip.style.animation = 'none'; // evita que tour-tooltip-in se repita
                tooltip.classList.remove('tour-tooltip--sliding');
                transitioning = false;
              }, SLIDE - FADE + 20);
            }));
          }, FADE);
        };

        if (inView) {
          positionAndSwap();
        } else if ('onscrollend' in window) {
          const onEnd = () => { window.removeEventListener('scrollend', onEnd); positionAndSwap(); };
          window.addEventListener('scrollend', onEnd, { once: true });
          setTimeout(() => { window.removeEventListener('scrollend', onEnd); positionAndSwap(); }, 500);
        } else {
          setTimeout(positionAndSwap, 350);
        }

        return;
      }

      // Fallback: target no visible aún (p.ej. requiere scroll o tab no cargada)
      const FALLBACK_DELAY = 400;
      CONTENT.forEach(id => {
        const el = document.getElementById(id);
        if (el) { el.style.transition = `opacity ${FADE}ms ease`; el.style.opacity = '0'; }
      });
      const activateEl2 = nextStep.activateSelector ? document.querySelector(nextStep.activateSelector) : null;
      if (activateEl2) activateEl2.click();
      setTimeout(() => {
        CONTENT.forEach(id => {
          const el = document.getElementById(id);
          if (el) { el.style.transition = ''; el.style.opacity = ''; }
        });
        current = n;
        renderStep(n);
        transitioning = false;
      }, FALLBACK_DELAY);

      return;
    }

    // Comportamiento original para otras transiciones
    if (!tooltip.hidden) {
      if (mob) {
        // Mobile: ocultar directamente, slide-out deja tooltip sin bottom-sheet y aparece arriba
        tooltip.hidden = true;
        current = n;
        renderStep(n);
        transitioning = false;
      } else {
        const outClass = dir > 0 ? 'tour-out-left' : 'tour-out-right';
        tooltip.classList.remove('tour-tooltip--centered', 'tour-tooltip--bottom-sheet');
        tooltip.classList.add(outClass);
        setTimeout(() => {
          tooltip.classList.remove('tour-out-left', 'tour-out-right');
          tooltip.style.animation = 'none';
          void tooltip.offsetWidth;
          tooltip.style.animation = '';
          current = n;
          renderStep(n);
          transitioning = false;
        }, 200);
      }
    } else {
      current = n;
      renderStep(n);
      transitioning = false;
    }
  }

  function finalizeClose() {
    clearSpotlight();
    if (ring) { ring.hidden = true; ring.style.opacity = ''; }
    dim.hidden   = true;
    shell.hidden = true;
    document.body.style.overflow = '';
    if (trapHandler) { releaseFocus(shell, trapHandler); trapHandler = null; }
    const card = modal && modal.querySelector('.onboarding-card');
    if (card) card.classList.remove('ob-dissolve');
    if (modal) modal.classList.remove('ob-closing');
    lsSet(LS_KEY, '1');
  }

  function closeTour() {
    const noMotion = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
    const card = (modal && !modal.hidden) ? modal.querySelector('.onboarding-card') : null;
    if (!card || noMotion) { finalizeClose(); return; }

    const r  = card.getBoundingClientRect();
    const cx = r.left + r.width / 2;
    const cy = r.top  + r.height / 2;
    card.classList.add('ob-dissolve');
    modal.classList.add('ob-closing');

    const layer = document.createElement('div');
    layer.className = 'ob-particle-layer';

    const wave = document.createElement('span');
    wave.className = 'ob-shockwave';
    wave.style.left   = cx + 'px';
    wave.style.top    = cy + 'px';
    wave.style.width  = (r.width  * 0.9) + 'px';
    wave.style.height = (r.height * 0.9) + 'px';
    layer.appendChild(wave);

    for (let i = 0; i < 36; i++) {
      const p     = document.createElement('span');
      const ang   = Math.random() * Math.PI * 2;
      const dist  = 90 + Math.random() * 240;
      const scale = (0.7 + Math.random() * 1.6).toFixed(2);
      const rot   = ((Math.random() - 0.5) * 320).toFixed(0);
      p.className = 'ob-particle';
      p.style.left = (r.left + Math.random() * r.width)  + 'px';
      p.style.top  = (r.top  + Math.random() * r.height) + 'px';
      p.style.setProperty('--dx',  (Math.cos(ang) * dist).toFixed(1) + 'px');
      p.style.setProperty('--dy',  (Math.sin(ang) * dist).toFixed(1) + 'px');
      p.style.setProperty('--s',   scale);
      p.style.setProperty('--rot', rot + 'deg');
      p.style.animationDelay = (Math.random() * 0.14).toFixed(2) + 's';
      layer.appendChild(p);
    }
    document.body.appendChild(layer);
    setTimeout(() => layer.remove(), 1200);
    setTimeout(finalizeClose, 620);
  }

  /* ── Eventos ──────────────────────────────────────────────── */
  const advance = () => current < TOTAL - 1 ? goTo(current + 1, 1) : closeTour();
  nextBtn.addEventListener('click', advance);
  mNext.addEventListener('click',   advance);
  skipBtn.addEventListener('click', closeTour);
  mSkip.addEventListener('click',   closeTour);
  dim.addEventListener('click',     closeTour);
  document.addEventListener('keydown', e => {
    const currentStep = TOUR_STEPS[current];
    if (e.key === 'Escape' && currentStep.type !== 'intereses' && !currentStep.noSkip) closeTour();
  });

  window.addEventListener('resize', () => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
      const step = TOUR_STEPS[current];
      if (!shell.hidden && step.type === 'spotlight') {
        const mob = isMob();
        const targetSel = (mob && step.mobileTargetSelector) ? step.mobileTargetSelector : step.targetSelector;
        const t = targetSel ? document.querySelector(targetSel) : null;
        if (t && isElementVisible(t)) {
          positionRing(t);
          if (mob) {
            tooltip.style.cssText = '';
            tooltip.classList.remove('tour-tooltip--centered');
            tooltip.classList.add('tour-tooltip--bottom-sheet');
            arrow.hidden = true;
          } else {
            tooltip.classList.remove('tour-tooltip--centered', 'tour-tooltip--bottom-sheet');
            arrow.hidden = false;
            positionTooltip(t, step.tooltipPosition);
          }
        } else {
          hideRing();
          if (mob) renderBottomSheet(step);
          else renderCenteredTooltip(step);
        }
      }
    }, 200);
  });

  /* ── Lanzar con pequeño retraso ───────────────────────────── */
  setTimeout(() => { shell.hidden = false; document.body.style.overflow = 'hidden'; renderStep(0); }, 800);
}());

/* ── BOTÓN VOLVER ARRIBA ─────────────────────────────────────── */
(function () {
  const btn   = document.getElementById('btn-volver-arriba');
  if (!btn) return;
  const appEl    = document.getElementById('app');
  const isAppScroll = !!(appEl && document.body.scrollHeight === document.body.clientHeight);
  function getScrollTop() { return isAppScroll ? appEl.scrollTop : window.scrollY; }
  function scrollToTop() {
    if (isAppScroll) appEl.scrollTo({ top: 0, behavior: 'smooth' });
    else             window.scrollTo({ top: 0, behavior: 'smooth' });
  }
  function onScroll() { btn.classList.toggle('visible', getScrollTop() > 400); }
  window.addEventListener('scroll', onScroll, { passive: true });
  if (appEl) appEl.addEventListener('scroll', onScroll, { passive: true });
  btn.addEventListener('click', scrollToTop);
}());


/* ── MODO LECTURA ENFOQUE ────────────────────────────────────── */
(function () {
  const layout = document.querySelector('.dashboard-layout');

  function colsExpandidas() {
    const pl = parseFloat(getComputedStyle(layout).paddingLeft)  || 0;
    const pr = parseFloat(getComputedStyle(layout).paddingRight) || 0;
    return `0px ${layout.clientWidth - pl - pr}px 0px`;
  }

  function aplicarEnfoque(activo) {
    document.querySelectorAll('.btn-modo-enfoque').forEach(b => {
      b.textContent = activo ? '✕ Salir de enfoque' : '📖 Modo Enfoque';
      b.setAttribute('aria-pressed', String(activo));
    });

    /* ── ENTRADA ──────────────────────────────────────────────── */
    if (activo) {
      document.body.classList.add('modo-enfoque-activo');
      if (!layout || window.innerWidth < 1101) return;

      /* Suprimir transición, expandir el grid al instante */
      layout.style.transition          = 'none';
      layout.style.gridTemplateColumns = colsExpandidas();
      layout.style.gap                 = '0px';

      /* Restaurar transición en el siguiente frame */
      requestAnimationFrame(() => {
        layout.style.transition = '';
      });

    /* ── SALIDA ───────────────────────────────────────────────── */
    } else {
      if (!layout || window.innerWidth < 1101) {
        document.body.classList.remove('modo-enfoque-activo');
        return;
      }

      /* 1. Quitar la clase INMEDIATAMENTE: los sidebars y el resto
            empiezan a reaparecer vía CSS transition al instante */
      document.body.classList.remove('modo-enfoque-activo');

      /* 2. Suprimir la transición del grid en este frame */
      layout.style.transition = 'none';

      /* 3. Limpiar los estilos inline → el grid vuelve a las columnas
            CSS sin ninguna animación (reset limpio e instantáneo) */
      layout.style.gridTemplateColumns = '';
      layout.style.gap                 = '';

      /* 4. Restaurar la transición en el siguiente frame para que
            futuras entradas sigan animándose */
      requestAnimationFrame(() => {
        layout.style.transition = '';
      });
    }
  }

  window._LI_setEnfoque = aplicarEnfoque;

  document.addEventListener('click', e => {
    if (!e.target.closest('.btn-modo-enfoque')) return;
    aplicarEnfoque(!document.body.classList.contains('modo-enfoque-activo'));
  });

  document.addEventListener('keydown', e => {
    if (e.key === 'Escape' && document.body.classList.contains('modo-enfoque-activo')) {
      aplicarEnfoque(false);
    }
  });

  window.addEventListener('resize', () => {
    if (!document.body.classList.contains('modo-enfoque-activo') || !layout) return;
    if (window.innerWidth < 1101) {
      layout.style.gridTemplateColumns = '';
      layout.style.gap                 = '';
    } else {
      layout.style.gridTemplateColumns = colsExpandidas();
      layout.style.gap                 = '0px';
    }
  }, { passive: true });
}());


/* ── BARRA DE PROGRESO DE LECTURA ────────────────────────────── */
(function () {
  const bar  = document.getElementById('reading-progress-bar');
  const fill = document.getElementById('reading-progress-fill');
  if (!bar || !fill) return;

  const appEl       = document.getElementById('app');
  const isAppScroll = !!(appEl && document.body.scrollHeight === document.body.clientHeight);
  const scrollEl    = isAppScroll ? appEl : document.documentElement;

  function updateProgress() {
    const scrollTop   = isAppScroll ? appEl.scrollTop : window.scrollY;
    const totalHeight = scrollEl.scrollHeight - scrollEl.clientHeight;
    if (totalHeight <= 0) return;
    const pct = Math.min(100, Math.max(0, (scrollTop / totalHeight) * 100));
    if (pct <= 0) {
      bar.classList.remove('visible');
      fill.style.transform = 'scaleX(0)';
    } else {
      bar.classList.add('visible');
      fill.style.transform = `scaleX(${pct / 100})`;
      bar.setAttribute('aria-valuenow', Math.round(pct));
    }
  }

  let rafPending = false;
  function scheduleProgress() {
    if (rafPending) return;
    rafPending = true;
    requestAnimationFrame(() => { rafPending = false; updateProgress(); });
  }

  window.addEventListener('scroll', scheduleProgress, { passive: true });
  if (appEl) appEl.addEventListener('scroll', scheduleProgress, { passive: true });
  updateProgress();
}());


/* ── SKELETON LOADING ────────────────────────────────────────── */
(function () {
  const docsLayout  = document.getElementById('documentos-list');

  /* Reveal docs cards */
  setTimeout(() => {
    if (!docsLayout) return;
    docsLayout.classList.remove('sk-init');
    const cards = docsLayout.querySelectorAll('.doc-card');
    cards.forEach((card, i) => {
      card.style.opacity    = '0';
      card.style.transition = `opacity 0.3s ${i * 0.07}s ease`;
    });
    requestAnimationFrame(() => {
      cards.forEach(card => { card.style.opacity = '1'; });
    });
    setTimeout(() => {
      cards.forEach(card => { card.style.opacity = ''; card.style.transition = ''; });
    }, 900);
  }, 540);
}());


